// 'card.render' decorators receive (card, tileSnapshot) — never a live DOM
// node — and return a patch describing what to add. See
// docs/architecture/PLUGIN_SYSTEM.md "The card.render decorator contract".
ctx.api.middleware.register({
  name: 'reading-time',
  operations: ['card.render'],
  handler: async function(card, tileSnapshot) {
    if (!card || !card.body) return null;
    var words = String(card.body).split(/\s+/).filter(Boolean).length;
    if (words < 30) return null;
    var minutes = Math.max(1, Math.round(words / 200));
    return {
      appendChildren: {
        '.card-content': [ctx.h('span', { className: 'plugin-reading-time' }, minutes + ' min read')]
      }
    };
  }
});

ctx.logger.info('Reading time estimates active');
